assets/workbench.css.text:
.stApp{background:#f5f7f6;color:#17332d;font-family:'Microsoft YaHei','PingFang SC','Segoe UI',sans-serif;}
.stMainBlockContainer{max-width:1200px;padding:3.25rem 28px 2rem;}
/* Keep Streamlit's platform controls in their own row; no fixed page height. */
header[data-testid="stHeader"]{position:fixed;height:3rem;min-height:3rem;background:white;}
/* Extend only the top surfaces; the existing content width and columns stay. */
.sp-brand,[data-testid="stTabs"] [role="tablist"]{box-shadow:0 0 0 100vmax white;clip-path:inset(0 -100vmax);}
.sp-brand{clip-path:inset(-4px -100vmax 0 -100vmax);}
.sp-brand{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 16px;background:white;}.sp-brand-main{display:flex;align-items:center;gap:11px;}.sp-logo{display:grid;place-items:center;width:36px;height:36px;border-radius:11px;background:#196e57;color:white;font-size:24px;font-weight:600;}.sp-brand strong{font-size:21px;line-height:1.4;}.sp-subtitle{font-size:13px;color:#65796f;}.sp-badge{font-size:13px;padding:4px 9px;border-radius:5px;background:#e9f1ec;color:#196e57;white-space:nowrap;}
[data-testid="stTabs"] [role="tablist"]{background:white;border-bottom:1px solid #dfe7e2;gap:25px;}[data-testid="stTabs"] [role="tab"]{min-height:56px;color:#65796f;white-space:nowrap;}[data-testid="stTabs"] [role="tab"][aria-selected="true"]{color:#196e57;}[data-testid="stTabs"] [role="tabpanel"]{padding-top:24px;}
.sp-eyebrow{font-size:13px;color:#196e57;margin:0 0 8px;}.sp-heading{font-size:28px!important;line-height:1.35!important;font-weight:600!important;color:#17332d;margin:0 0 12px!important;}.sp-lead{color:#65796f;font-size:16px;line-height:1.65;margin-bottom:24px;}
.st-key-chat_card,.st-key-execution_card{background:white;border-radius:12px;}.st-key-chat_card [data-testid="stChatMessage"]{overflow-wrap:anywhere;}.st-key-chat_card [data-testid="stChatMessage"]:has([data-testid="stChatMessageAvatarUser"]){background:#e7efe9;}.st-key-chat_card [data-testid="stChatInput"]{background:white;}.st-key-chat_card [data-testid="stChatInput"] textarea{font-size:16px;}
.sp-empty{padding:32px 8px;text-align:center;}.sp-empty h3{font-size:21px!important;}.sp-empty p{color:#65796f;}.sp-facts{border:1px solid #dfe7e2;border-radius:9px;padding:12px 14px;margin-top:16px;}.sp-facts div{display:flex;justify-content:space-between;gap:16px;margin:7px 0;}.sp-facts dt{color:#65796f;font-size:14px;max-width:40%;}.sp-facts dd{margin:0;text-align:right;font-weight:600;overflow-wrap:anywhere;}
.sp-section{border-top:1px solid #dfe7e2;padding-top:28px;margin-top:24px;}.sp-section-label{font-size:13px;color:#196e57;}.sp-zoom{max-width:100%;max-height:480px;overflow:auto;background:white;border:1px solid #dfe7e2;}.sp-zoom img{display:block;width:1680px;max-width:none;height:auto;}.sp-footer{border-top:1px solid #dfe7e2;padding:20px 0;color:#65796f;font-size:13px;margin-top:28px;}
.st-key-workspace [data-testid="stColumn"],.st-key-about_content [data-testid="stColumn"]{min-width:0;}.st-key-about_content [data-testid="stImage"] img{border-radius:10px;}
.st-key-about_content h3,.st-key-execution_card h3{font-size:20px!important;line-height:1.5!important;font-weight:600!important;}
@media(max-width:600px){.st-key-about_content h3,.st-key-execution_card h3{font-size:18px!important;}}
@media(max-width:959px){.st-key-workspace [data-testid="stHorizontalBlock"]:has(> [data-testid="stColumn"]){flex-direction:column;}.st-key-workspace [data-testid="stHorizontalBlock"] > [data-testid="stColumn"]{width:100%!important;flex:1 1 100%!important;}}
@media(max-width:600px){.stMainBlockContainer{padding:3.25rem 16px 1.5rem;}.sp-brand{flex-wrap:wrap;padding:12px 0;}.sp-logo{width:32px;height:32px;font-size:22px;}.sp-brand strong{font-size:18px;}.sp-heading{font-size:24px!important;line-height:1.4!important;}[data-testid="stTabs"] [role="tablist"]{gap:12px;}[data-testid="stTabs"] [role="tab"]{flex:1;padding:10px 0;min-height:48px;}[data-testid="stTabs"] [role="tab"] p{font-size:14px;}.st-key-chat_intro [data-testid="stHorizontalBlock"],.st-key-about_content [data-testid="stHorizontalBlock"]{flex-direction:column;}.st-key-chat_intro [data-testid="stColumn"],.st-key-about_content [data-testid="stColumn"]{width:100%!important;flex:1 1 100%!important;}.sp-zoom{max-height:420px;}button{min-height:44px!important;}.sp-lead{margin-bottom:18px;}}
.st-key-code_guide{min-width:0;overflow-wrap:anywhere;}.st-key-code_guide [data-testid="stCode"]{max-width:100%;min-width:0;}.st-key-code_guide [data-testid="stCode"] pre{overflow:auto!important;}
/* Scoped surfaces for existing introduction groups and code chapters only. */
.st-key-about_content [class*="st-key-about_panel_"],.st-key-code_guide [class*="st-key-code_panel_"]{background:#fff;border:1px solid #dfe7e2;border-radius:12px;padding:22px;box-shadow:0 2px 8px rgba(23,51,45,.035);min-width:0;max-width:100%;box-sizing:border-box;margin-bottom:6px;}
.st-key-about_content .sp-section{border-top:0;padding-top:0;margin-top:0;}
.st-key-about_content [class*="st-key-about_inset_"]{background:#fff;border:1px solid #dfe7e2;border-radius:10px;padding:16px;min-width:0;max-width:100%;box-sizing:border-box;}
.st-key-code_guide [data-testid="stCode"],.st-key-code_guide [data-testid="stCode"] pre{background:#eef3f0;}
.st-key-code_guide .st-key-full_source details{background:#fff;border:1px solid #dfe7e2;border-radius:12px;box-shadow:0 2px 8px rgba(23,51,45,.035);}
.st-key-code_guide .st-key-full_source summary{padding:14px 22px;}
.st-key-code_guide .st-key-full_source [data-testid="stExpanderDetails"]{padding:8px 22px 22px;min-width:0;}
@media(max-width:600px){.st-key-about_content [class*="st-key-about_panel_"],.st-key-code_guide [class*="st-key-code_panel_"]{padding:15px;}.st-key-code_guide .st-key-full_source summary{padding:14px 15px;}.st-key-code_guide .st-key-full_source [data-testid="stExpanderDetails"]{padding:8px 15px 15px;}}
